48	/**
49	 * In-memory implementation of {@link HoodiePairData} holding internally a {@link Stream} of {@link Pair}s.
50	 *
51	 * {@link HoodieListData} can have either of the 2 execution semantics:
52	 *
53	 * <ol>
54	 *   <li>Eager: with every operation being executed right away</li>
55	 *   <li>Lazy: with every operation being "stacked up", with it execution postponed until
56	 *   "terminal" operation is invoked</li>
57	 * </ol>
58	 *
59	 *
60	 * NOTE: This is an in-memory counterpart for {@code HoodieJavaPairRDD}, and it strives to provide
61	 *       similar semantic as RDD container -- all intermediate (non-terminal, not de-referencing
62	 *       the stream like "collect", "groupBy", etc) operations are executed *lazily*.
63	 *       This allows to make sure that compute/memory churn is minimal since only necessary
64	 *       computations will ultimately be performed.
65	 *
66	 *       Please note, however, that while RDD container allows the same collection to be
67	 *       de-referenced more than once (ie terminal operation invoked more than once),
68	 *       {@link HoodieListData} allows that only when instantiated w/ an eager execution semantic.
69	 *
70	 * @param <K> type of the key in the pair
71	 * @param <V> type of the value in the pair
72	 */
73	public class HoodieListPairData<K, V> extends HoodieBaseListData<Pair<K, V>> implements HoodiePairData<K, V> {
74	
75	  private HoodieListPairData(List<Pair<K, V>> data, boolean lazy) {
76	    super(data, lazy);
77	  }
78	
79	  HoodieListPairData(Stream<Pair<K, V>> dataStream, boolean lazy) {
80	    super(dataStream, lazy);
81	  }
82	
83	  @Override
84	  public List<Pair<K, V>> get() {
85	    return collectAsList();
86	  }
87	
88	  @Override
89	  public void persist(String cacheConfig) {
90	    // no-op
91	  }
92	
93	  @Override
94	  public void unpersist() {
95	    // no-op
96	  }
97	
98	  @Override
99	  public HoodieData<K> keys() {
100	    return new HoodieListData<>(asStream().map(Pair::getKey), lazy);
101	  }
102	
103	  @Override
104	  public HoodieData<V> values() {
105	    return new HoodieListData<>(asStream().map(Pair::getValue), lazy);
106	  }
107	
108	  @Override
109	  public Map<K, Long> countByKey() {
110	    try (Stream<Pair<K, V>> stream = asStream()) {
111	      return stream.collect(Collectors.groupingBy(Pair::getKey, Collectors.counting()));
112	    }
113	  }
114	
115	  @Override
116	  public HoodiePairData<K, Iterable<V>> groupByKey() {
117	    Collector<Pair<K, V>, ?, List<V>> mappingCollector = Collectors.mapping(Pair::getValue, Collectors.toList());
118	    Collector<Pair<K, V>, ?, Map<K, List<V>>> groupingCollector =
119	        Collectors.groupingBy(Pair::getKey, mappingCollector);
120	
121	    try (Stream<Pair<K, V>> s = asStream()) {
122	      Map<K, List<V>> groupedByKey = s.collect(groupingCollector);
123	      return new HoodieListPairData<>(
124	          groupedByKey.entrySet().stream().map(e -> Pair.of(e.getKey(), e.getValue())),
125	          lazy
126	      );
127	    }
128	  }
129	
130	  @Override
131	  public HoodiePairData<K, V> reduceByKey(SerializableBiFunction<V, V, V> combiner, int parallelism) {
132	    try (Stream<Pair<K, V>> stream = asStream()) {
133	      Map<K, java.util.Optional<V>> reducedMap = stream.collect(
134	          Collectors.groupingBy(
135	              Pair::getKey,
136	              HashMap::new,
137	              Collectors.mapping(Pair::getValue, Collectors.reducing(combiner::apply))));
138	
139	      return new HoodieListPairData<>(
140	          reducedMap.entrySet()
141	              .stream()
142	              .map(e -> Pair.of(e.getKey(), e.getValue().orElse(null))),
143	          lazy
144	      );
145	    }
146	  }
147	
148	  @Override
149	  public <O> HoodieData<O> map(SerializableFunction<Pair<K, V>, O> func) {
150	    Function<Pair<K, V>, O> uncheckedMapper = throwingMapWrapper(func);
151	    return new HoodieListData<>(asStream().map(uncheckedMapper), lazy);
152	  }
153	
154	  @Override
155	  public <W> HoodiePairData<K, W> mapValues(SerializableFunction<V, W> func) {
156	    Function<V, W> uncheckedMapper = throwingMapWrapper(func);
