package org.apache.hudi.metadata;

import org.apache.hudi.common.data.HoodieData;
import org.apache.hudi.common.data.HoodiePairData;
import org.apache.hudi.common.function.SerializableFunctionUnchecked;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.util.List;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;

/**
 * Manages the lifecycle of intermediate, potentially uncached, distributed data collections
 * ({@link HoodieData} / {@link HoodiePairData}) produced while reading from the metadata table.
 *
 * <p>Some metadata read paths build up chains of distributed collections (e.g. Spark RDDs) that
 * are cached but never handed back to the caller when an exception is thrown midway. Left behind,
 * these cached collections leak memory on the executors. This manager tracks such collections on a
 * per-thread basis and, if the wrapped operation throws, recursively un-persists every tracked
 * collection (and its upstream dependencies) before re-throwing the original exception.
 *
 * <p>Tracking is isolated per thread using the thread id, so cleanup triggered in one thread never
 * affects collections tracked by another thread.
 */
public class HoodieDataCleanupManager {

  private static final Logger LOG = LoggerFactory.getLogger(HoodieDataCleanupManager.class);

  // Tracks persisted data per thread (keyed by thread id) so that cleanup remains thread isolated.
  private final ConcurrentHashMap<Long, List<Object>> threadPersistedData = new ConcurrentHashMap<>();

  public HoodieDataCleanupManager() {
  }

  /**
   * Tracks a {@link HoodiePairData} so it can be released if the surrounding operation fails.
   *
   * @param data the {@link HoodiePairData} to track for the current thread.
   */
  public void trackPersistedData(HoodiePairData<?, ?> data) {
    track(data);
  }

  /**
   * Tracks a {@link HoodieData} so it can be released if the surrounding operation fails.
   *
   * @param data the {@link HoodieData} to track for the current thread.
   */
  public void trackPersistedData(HoodieData<?> data) {
    track(data);
  }

  private void track(Object data) {
    long threadId = Thread.currentThread().getId();
    threadPersistedData.computeIfAbsent(threadId, k -> new CopyOnWriteArrayList<>()).add(data);
  }

  /**
   * Executes the provided {@code operation}, returning its result on success. If the operation
   * throws, all data collections tracked for the current thread are un-persisted (along with their
   * upstream dependencies) and the tracking state for the thread is cleared before the original
   * exception is re-thrown.
   *
   * <p>Regardless of the outcome, the tracking state for the current thread is removed so the
   * manager does not accumulate entries across invocations.
   *
   * @param operation the operation to execute.
   * @param <T>       the type of the operation's result.
   * @return the result of the operation.
   */
  public <T> T ensureDataCleanupOnException(SerializableFunctionUnchecked<Void, T> operation) {
    long threadId = Thread.currentThread().getId();
    try {
      return operation.apply(null);
    } catch (Exception e) {
      unpersistTrackedData(threadId);
      throw e;
    } finally {
      threadPersistedData.remove(threadId);
    }
  }

  private void unpersistTrackedData(long threadId) {
    List<Object> persistedData = threadPersistedData.get(threadId);
    if (persistedData == null) {
      return;
    }
    for (Object data : persistedData) {
      try {
        if (data instanceof HoodieData) {
          ((HoodieData<?>) data).unpersistWithDependencies();
        } else if (data instanceof HoodiePairData) {
          ((HoodiePairData<?, ?>) data).unpersistWithDependencies();
        }
        // Silently skip null entries and objects that are neither HoodieData nor HoodiePairData.
      } catch (Exception e) {
        // Continue cleaning up the remaining tracked objects even if one fails to unpersist.
        LOG.warn("Failed to unpersist tracked data during exception cleanup", e);
      }
    }
  }

  /**
   * Exposes the per-thread tracking map. Package-private for testing.
   *
   * @return the map of thread id to the list of tracked data collections.
   */
  ConcurrentHashMap<Long, List<Object>> getThreadPersistedData() {
    return threadPersistedData;
  }
}
